import React from "react";
import "../headercss/categorycss.css";
import Button from '@mui/material/Button';
import Menu from '@mui/material/Menu';
import MenuItem from '@mui/material/MenuItem';

export default function Category() {
   
    const categories = [
  { name: "Glocery", img: "https://rukminim1.flixcart.com/flap/64/64/image/29327f40e9c4d26b.png?q=100" },
  { name: "Mobiles", img: "https://rukminim1.flixcart.com/flap/64/64/image/22fddf3c7da4c4f4.png?q=100  " },
  { name: "Fashion", img: "data:image/jpeg;base64," },
  {name:"Electronics",img:"data:image/jpeg;base64,"},
  { name: "Home & Furnitures",img:"data:image/webp;base64," },
    {name:"Appliances",img:"data:image/jpeg;base64,"},
  {name:"Toys",img:"data:image/jpeg;base64,"},
  {name:"Two Wheelers",img:"data:image/jpeg;base64,"},
]; const [anchorEl, setAnchorEl] = React.useState(null);
const [selectedIndex, setSelectedIndex] = React.useState(null); 

const open = Boolean(anchorEl);

const handleClick = (event, index) => {
  setAnchorEl(event.currentTarget);
  setSelectedIndex(index); 
};

const handleClose = () => {
  setAnchorEl(null);
     setSelectedIndex(null);
};
const menucategory = [
  ["Fruits", "Vegetables", "Grains", "Dairy", "Meat", "Seafood", "Beverages", "Sweets"],
  ["Oppo", "Vivo", "Realme", "Xiaomi", "Apple", "Samsung"],
  ["Tshirts", "Jeans", "Shoes", "Accessories", "Bags"],
  ["TV", "Speakers", "Headphones", "Smartwatches"],
  ["Bedsheet", "Blanket", "Covers"],
  ["Tava", "PressureCooker", "Blender", "Microwave", "Refrigerator"],
  ["Books", "Sports", "Toys", "Games"],
  ["PetrolVehicles", "DieselVehicles", "ElectricVehicles"]
];
return (
  <>
  
    <div className="category-container">
      {categories.map((category, index) => (
        <div className="category-link" key={index}>
          <div className="category-item">
            <img
              src={category.img}
              alt={category.name}
              className="category-image"
            />
            <Button
              className="category-name"
              id="demo-positioned-button"
              aria-controls={open ? "demo-positioned-menu" : undefined}
              aria-haspopup="true"
              aria-expanded={open ? "true" : undefined}
              onClick={(e) => handleClick(e, index)} // <-- pass index
            >
               {category.name}
            </Button>
          </div>
        </div>
      ))}
    </div>
    <Menu
      id="demo-positioned-menu"
      anchorEl={anchorEl}
      open={open}
      onClose={handleClose}
      anchorOrigin={{
        vertical: "bottom",
        horizontal: "left",
      }}
      transformOrigin={{
        vertical: "top",
        horizontal: "left",
      }}
    >
        {selectedIndex !== null &&
        menucategory[selectedIndex].map((item, idx) => (
          <MenuItem key={idx} onClick={handleClose}>
            {item}
          </MenuItem>
        ))}
    </Menu>
  </>
);}
